'use strict';
// v44 Slice 1 regression harness (not a test file itself). Runs a broad, deterministic set of
// White Orchard progression scenarios against the modules in `dir` and returns a JSON-safe summary.
// slice1-wo-baseline.fixture.json was generated by running this harness against the untouched
// v44 source (commit 16286447); slice1-migration.test.cjs asserts the current source reproduces it.
const fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
function load(dir){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','progression-data.js','progression-engine.js','departure.js'])vm.runInContext(fs.readFileSync(path.join(dir,f),'utf8'),c,{filename:f});return c.window;}
const json=x=>JSON.parse(JSON.stringify(x));
function run(dir){
 const w=load(dir),data=w.PHOENIX_PROGRESS_DATA,{tasks,hubs}=w.PHOENIX_ROUTE,e=w.createPhoenixProgress(data,tasks,hubs),fresh=()=>e.init();
 const ids=Object.keys(data.objectiveIndex),qs=Object.keys(data.quests);
 const graph=Object.fromEntries(ids.map(id=>{const o=data.objectiveIndex[id];return [id,json({quest:o.quest,requires:o.requires,conditionalRequires:o.conditionalRequires,branch:o.branch,choice:o.choice,optional:o.optional,grants:o.grants,risk:o.risk})];}));
 const view=p=>({facts:e.facts(p),status:Object.fromEntries(qs.map(q=>[q,e.status(q,p)])),availability:Object.fromEntries(qs.map(t=>[t,e.availability(t,p)])),counts:Object.fromEntries(qs.map(q=>[q,e.counts(q,p)]))});
 const out={graph,scenarios:{}};
 const rec=(name,fn)=>{let r;try{r=fn();r=r&&r.progress?{plan:json(r),view:json(view(r.progress))}:json(r);}catch(err){r={error:String(err.message)};}out.scenarios[name]=r;};
 rec('fresh',()=>({view:view(fresh())}));
 for(const id of ids){rec('objective:'+id,()=>e.plan(fresh(),{},{kind:'objective',id,value:true}));rec('objective-nocatchup:'+id,()=>e.plan(fresh(),{},{kind:'objective',id,value:true},{catchup:false}));}
 const all=e.plan(fresh(),{},{kind:'objective',id:'q-lilac:leave',value:true}).progress;
 // Corrections from a fully departed save are slow in the v44 engine (~0.4s each), so a representative set is used.
 for(const id of ['q-lilac:ghouls','q-lilac:garrison','q-lilac:contract','q-lilac:leave','q-beast:buckthorn','q-beast:kill','q-beast:reward','q-incident:bandits','q-pan:door'])rec('correct-after-leave:'+id,()=>e.plan(all,{},{kind:'objective',id,value:false}));
 for(const q of qs){rec('quest:'+q,()=>e.plan(fresh(),{},{kind:'quest',quest:q,value:true}));rec('quest-undo:'+q,()=>e.plan(e.plan(fresh(),{},{kind:'quest',quest:q,value:true}).progress,{},{kind:'quest',quest:q,value:false}));rec('fail:'+q,()=>e.plan(fresh(),{},{kind:'quest-failed',quest:q,value:true}));rec('legacy:'+q,()=>({view:view(e.init({},{[q]:true}))}));rec('reconcile:'+q,()=>e.plan(e.init({},{[q]:true}),{[q]:true},{kind:'reconcile-legacy',quest:q}));}
 for(const [key,c] of Object.entries(data.choices))for(const [v] of c.options){const q=Object.values(data.objectiveIndex).find(o=>o.choice===key).quest;rec('choice:'+key+'='+v,()=>e.plan(fresh(),{},{kind:'quest',quest:q,value:true},{choices:{[key]:v}}));}
 for(const m of Object.keys(data.milestones)){rec('milestone:'+m,()=>e.plan(fresh(),{},{kind:'milestone',id:m}));rec('story-set-from-all:'+m,()=>e.plan(all,{},{kind:'story-set',id:m}));}
 const started=['q-missing:dune','q-firestarter:clues','q-pan:door','q-death:brew'].reduce((p,id)=>e.plan(p,{},{kind:'objective',id,value:true}).progress,fresh());
 rec('departure-with-started',()=>e.plan(started,{},{kind:'milestone',id:'departed'}));
 rec('inn-fight-unconfirmed',()=>e.plan(fresh(),{},{kind:'objective',id:'q-incident:bandits',value:true}));
 rec('inn-fight-confirmed',()=>e.plan(fresh(),{},{kind:'objective',id:'q-incident:bandits',value:true},{confirmDeparture:true}));
 rec('skip-optional',()=>e.plan(fresh(),{},{kind:'skip',id:'q-devil:notice',skip:true,value:true}));
 for(const [label,p] of [['fresh',fresh()],['started',started],['all',all]]){const state={progress:p,completed:{}};rec('departure-build:'+label,()=>w.PhoenixDeparture.build({state,engine:e,tasks}));}
 return out;
}
module.exports={run};
if(require.main===module){const dir=process.argv[2]||__dirname,outFile=process.argv[3];const r=JSON.stringify(run(dir));if(outFile)fs.writeFileSync(outFile,r);else process.stdout.write(r);}
